css:
.arcs { font-size: 12px; color: #1f272e; }
.arcs-head { width: 100%; margin-bottom: 18px; }
.arcs-head td { vertical-align: top; }
.arcs-right { text-align: right; }
.arcs-co { font-size: 14px; font-weight: 600; }
.arcs-title { font-size: 18px; font-weight: 600; margin: 4px 0; }
.arcs-cust { font-size: 14px; font-weight: 600; }
.arcs-muted { color: #6b7480; }
.arcs-table { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
.arcs-table th, .arcs-table td { border-bottom: 1px solid #e3e5e8; padding: 5px 6px; text-align: left; }
.arcs-table th { color: #6b7480; font-weight: 500; }
.arcs .arcs-n { text-align: right; }
.arcs-total td { font-weight: 600; border-top: 1px solid #c9ced4; }
.arcs-h { font-weight: 600; font-size: 13px; margin: 12px 0 6px; }
.arcs-box { border: 1px solid #e3e5e8; border-radius: 6px; padding: 8px 10px; white-space: pre-wrap; }
.arcs-foot { margin-top: 18px; }
